<?php
require __DIR__.'/../includes/bootstrap.php'; requireLogin();
$id=(int)($_GET['id']??0); $quantity=max(1,min(10,(int)($_GET['quantity']??1)));
$stmt=$pdo->prepare("SELECT * FROM events WHERE id=? AND status='published'"); $stmt->execute([$id]); $event=$stmt->fetch();
if(!$event) exit('Événement introuvable');
$remaining=max(0,(int)$event['capacity']-(int)$event['sold']); $quantity=min($quantity,$remaining); $total=(float)$event['price']*$quantity;
$error='';
if($_SERVER['REQUEST_METHOD']==='POST') { verifyCsrf(); if($quantity<1 || $quantity>$remaining) $error='Nombre de places invalide.'; else { $method=$_POST['payment_method']??'wave'; $pdo->beginTransaction(); try { $ref='SB'.date('YmdHis').random_int(100,999); $stmt=$pdo->prepare('INSERT INTO orders(user_id,event_id,quantity,total,payment_method,payment_status,reference) VALUES(?,?,?,?,?,"paid",?)'); $stmt->execute([$_SESSION['user']['id'],$id,$quantity,$total,$method,$ref]); $orderId=$pdo->lastInsertId(); for($i=0;$i<$quantity;$i++){ $code='TKT-'.$ref.'-'.$str_pad((string)($i+1),3,'0',STR_PAD_LEFT); $pdo->prepare('INSERT INTO tickets(order_id,code) VALUES(?,?)')->execute([$orderId,$code]); } $pdo->prepare('UPDATE events SET sold=sold+? WHERE id=?')->execute([$quantity,$id]); $pdo->commit(); flash('success','Réservation confirmée ! Vos billets sont disponibles.'); redirect('/dashboard.php'); } catch(Throwable $e){ $pdo->rollBack(); $error='Le paiement n’a pas pu être effectué.'; } }}
$pageTitle='Paiement'; require __DIR__.'/../includes/header.php';
?>
<section class="checkout"><div class="checkout-form auth-card"><span class="eyebrow">Dernière étape</span><h1>Finaliser la réservation</h1><?php if($error):?><div class="alert error"><?= esc($error) ?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?= csrfToken() ?>"><h3>Moyen de paiement</h3><label class="payment-option"><input type="radio" name="payment_method" value="wave" checked><b>Wave</b><span>Paiement mobile</span></label><label class="payment-option"><input type="radio" name="payment_method" value="orange"><b>Orange Money</b><span>Paiement mobile</span></label><label class="payment-option"><input type="radio" name="payment_method" value="card"><b>Carte bancaire</b><span>Visa / Mastercard</span></label><button class="btn btn-full">Payer <?= formatMoney($total) ?></button></form></div><aside class="order-summary"><h3>Votre réservation</h3><img src="<?= esc($event['image']) ?>" alt=""><h2><?= esc($event['title']) ?></h2><p><?= esc($event['location']) ?></p><div><span>Billets × <?= $quantity ?></span><strong><?= formatMoney($total) ?></strong></div><div class="total"><span>Total</span><strong><?= formatMoney($total) ?></strong></div></aside></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
